  function bookshopReadingSample(options) {
    const model2 = bookshopReaderModel();
    const returning = options.practice.id === "bookshop-small-change-available";
    const section = model2.payload.sections[returning ? 1 : 0];
    const question2 = model2.payload.questions[returning ? 1 : 0];
    const sample = element("section", "academy-bookshop-reading-sample");
    sample.dataset.bookshopReading = BOOKSHOP_READER.sourceSegmentId;
    sample.dataset.sourceId = BOOKSHOP_READER.provenance.sourceId;
    sample.dataset.sourcePages = BOOKSHOP_READER.provenance.locus.pdfPages.join("-");
    const tape = element("p", "academy-bookshop-reading-tape");
    tape.textContent = options.language === "ja" ? "試し読み・ももたろう" : "Sample page · Momotarou";
    const passage = element("p", "academy-bookshop-reading-passage");
    passage.lang = "ja";
    passage.textContent = section.paragraphs[returning ? 0 : 1] ?? section.paragraphs[0] ?? "";
    const prompt2 = element("p", "academy-bookshop-reading-prompt");
    prompt2.textContent = question2.prompt[options.language];
    const choices2 = element("div", "academy-bookshop-reading-choices");
    choices2.setAttribute("role", "group");
    choices2.setAttribute("aria-label", question2.prompt[options.language]);
    const status = element("p", "academy-bookshop-reading-status");
    status.setAttribute("role", "status");
    status.setAttribute("aria-live", "polite");
    for (const option2 of question2.options) {
      const button2 = element("button", "academy-bookshop-reading-choice");
      button2.type = "button";
      button2.dataset.readingChoice = option2.id;
      button2.lang = "ja";
      button2.textContent = option2.label;
      button2.addEventListener("click", () => {
        if (option2.id !== question2.correctOptionId) {
          status.textContent = model2.payload.feedback.lapse.repairPrompt[options.language];
          return;
        }
        sample.dataset.readingComplete = "true";
        status.textContent = model2.payload.feedback.pass.explanation[options.language];
        choices2.querySelectorAll("button").forEach((choice2) => {
          choice2.disabled = true;
        });
      });
      choices2.append(button2);
    }
    sample.append(tape, passage, prompt2, choices2, status);
    return sample;
  }
